  'create_workspace',
  'join_workspace',
  'create_problem',
  'claim_problem',
  'update_problem',
  'list_problems',
  'post_message',
  'read_channel',
  'workspace_status',
  'workspace_digest',
] as const;

/** The five canary operations (catalog 35 → 40). */
export const CELLD_NEW_OPERATIONS = [
  'declare_work_intent',
  'record_work_change',
  'list_impacts',
  'acknowledge_impact',
  'read_workspace_events',
] as const;

/** Celld operations that mutate the cell (require CommandMetadataV1). */
export const CELLD_MUTATION_OPERATIONS = [
  'create_workspace',
  'join_workspace',
  'create_problem',
  'claim_problem',
  'update_problem',
  'post_message',
  'declare_work_intent',
  'record_work_change',
  'acknowledge_impact',
] as const;

export type CelldMutationOperation = (typeof CELLD_MUTATION_OPERATIONS)[number];
export type CelldOperation =
  | (typeof CELLD_SUPPORTED_EXISTING_OPERATIONS)[number]
