export interface HubHandler {
  /**
   * `agentId` is the identity the request already resolved to (see
   * identity-resolver.ts) — null only for the identity-minting stage-0
   * operations. `requestPrincipal` is the authenticated principal of the
   * request in hosted multi-tenant mode; it is what register/quick_join
   * stamp onto new records (c1) and what the transfer_coordinator recovery
   * path checks (c6). Local fs mode leaves it undefined.
   */
  handle(
    agentId: string | null,
    operation: string,
    args: Record<string, any>,
    requestPrincipal?: string,
  ): Promise<unknown>;
}

export interface HubHandlerOptions {
  /**
   * Hosted multi-tenant deployment: bind new agents to the authenticated
   * principal and honour the owning-principal transfer path. Local fs mode
   * (the only mode wired today) leaves this false.
   */
  hostedMode?: boolean;
}

function getDisclosureStage(operation: string): DisclosureStage {
  if ((STAGE_OPERATIONS[0] as string[]).includes(operation)) return 0;
  if ((STAGE_OPERATIONS[1] as string[]).includes(operation)) return 1;
  return 2;
}

/**
 * The five coordination operations (RFC 0001) exist only on celld-backed
 * workspaces — this filesystem HubHandler has no cell, so every one of them
 * is refused here before any storage or manager call runs. `src/hub` must
 * not import `src/celld` (an architecture test enforces this), so the error
 * carries the stable code and retryability as plain properties rather than a
 * shared celld error class.
 */
function celldBackendRequiredError(operation: string): Error {
  const err = new Error(
    `[OPERATION_REQUIRES_CELLD_BACKEND] '${operation}' is a coordination operation ` +
      "(RFC 0001) that only runs on a celld-backed workspace. This workspace uses " +
      "filesystem storage — create it with backend: 'celld' to use this operation.",
  );
  return Object.assign(err, { code: 'OPERATION_REQUIRES_CELLD_BACKEND', retryable: false });
}

/** Operations that require workspace membership check */
const WORKSPACE_OPERATIONS = new Set<string>(STAGE_OPERATIONS[2]);

export function createHubHandler(
  storage: HubStorage,
  thoughtStore: ThoughtStore,
