        if (operation === 'whoami') {
          return identity.whoami(agentId);
        }
        if (operation === 'create_workspace') {
          const result = await workspace.createWorkspace(agentId, args as any);
          emit({
            type: 'workspace_created',
            workspaceId: result.workspaceId,
            data: {
              workspaceId: result.workspaceId,
              name: args.name,
              createdBy: agentId
            }
          });
          return result;
        }
        if (operation === 'join_workspace') {
          const joinResult = await workspace.joinWorkspace(agentId, args as any);
          emit({
            type: 'workspace_joined',
            workspaceId: joinResult.workspace.id,
            data: {
              agentId,
              name: agent.name,
              workspaceId: joinResult.workspace.id,
            },
          });
          return joinResult;
        }
        if (operation === 'transfer_coordinator') {
          const { workspaceId, toAgentId } = args as {
            workspaceId?: string; toAgentId?: string;
          };
          if (!workspaceId) throw new Error('transfer_coordinator requires workspaceId');
          if (!toAgentId) throw new Error('transfer_coordinator requires toAgentId');
